<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { message, Modal } from "ant-design-vue";
import { exportResults, getResultDetail, getBatchResultSummary, getConversationResultDetail, listResults, type ConversationResultSummary, type InspectionResult } from "@/api/results";
import { dictionaryLabel, getCachedDictionaries, type DictionaryItem } from "@/api/dictionaries";
import { usePermission } from "@/composables/permission";
import { createFeedback, createSample, requestReview } from "@/api/quality";

interface RuleBreakdown { ruleId?: string; ruleName?: string; ruleCode?: string; category?: string; status: string; deduction?: number; score?: number; riskLevel?: string; reason?: string; veto?: boolean }
interface ResultEvidence { ruleId?: string; text?: string; start?: number; end?: number; sequenceNo?: number }
interface ResultSuggestion { ruleId?: string; title?: string; content?: string }

const results = ref<InspectionResult[]>([]), total = ref(0), page = ref(1), pageSize = ref(20), loading = ref(false);
const conversationSummary = ref<ConversationResultSummary[]>([]);
const conversationMessages = ref<any[]>([]), conversationResults = ref<InspectionResult[]>([]);
const detailOpen = ref(false), detailLoading = ref(false); const detail = ref<any>();
const resultStatuses = ref<DictionaryItem[]>([{ value: "HIT", label: "命中", tagType: "error" }, { value: "NOT_HIT", label: "未命中", tagType: "success" }, { value: "PARTIAL_ERROR", label: "部分错误", tagType: "warning" }, { value: "ERROR", label: "错误", tagType: "error" }]);
const riskLevels = ref<DictionaryItem[]>([{ value: "HIGH", label: "高风险" }, { value: "MEDIUM", label: "中风险" }, { value: "LOW", label: "低风险" }]);
const filters = ref({ taskId: undefined as string|undefined, agentId: undefined as string|undefined, ownerId: undefined as string|undefined, groupId: undefined as string|undefined, status: undefined as string|undefined, minScore: undefined as number|undefined, maxScore: undefined as number|undefined, speakerRole: undefined as string|undefined, riskLevel: undefined as string|undefined });
const { can } = usePermission();

function parseArray<T>(value?: string): T[] { if (!value) return []; try { const parsed = JSON.parse(value); return Array.isArray(parsed) ? parsed : []; } catch { return []; } }
function snapshotRules(): any[] { try { const parsed = JSON.parse(detail.value?.task?.ruleSnapshotJson || "[]"); return Array.isArray(parsed) ? parsed : Array.isArray(parsed.rules) ? parsed.rules : []; } catch { return []; } }
const breakdown = computed(() => {
  const rules = snapshotRules();
  return parseArray<RuleBreakdown>(detail.value?.result?.ruleBreakdownJson).map((item) => {
    const rule = rules.find((candidate) => candidate.id === item.ruleId);
    return { ...item, ruleName: item.ruleName || rule?.name, ruleCode: item.ruleCode || rule?.code, category: item.category || rule?.category, veto: item.veto ?? rule?.veto };
  });
});
const violations = computed(() => breakdown.value.filter((item) => item.status === "HIT"));
const diagnostics = computed(() => breakdown.value.filter((item) => item.status?.endsWith("ERROR")));
const evidences = computed(() => parseArray<ResultEvidence>(detail.value?.result?.evidenceJson));
const suggestions = computed(() => parseArray<ResultSuggestion>(detail.value?.result?.suggestionJson));
function ruleTitle(item: RuleBreakdown, index: number) { return item.ruleName || item.ruleCode || `违规项 ${index + 1}`; }
function ruleEvidence(ruleId?: string): ResultEvidence[] { const matched = evidences.value.filter((item) => item.ruleId === ruleId); if (matched.length) return matched; if (evidences.value.length === 1) return evidences.value; return detail.value?.result?.evidence ? [{ ruleId, text: detail.value.result.evidence }] : []; }
function ruleSuggestions(ruleId?: string) { const matched = suggestions.value.filter((item) => item.ruleId === ruleId); return matched.length ? matched : suggestions.value.length === 1 ? suggestions.value : []; }
function resultLabel(value?: string) { return dictionaryLabel(resultStatuses.value, value); }
function riskLabel(value?: string) { return dictionaryLabel(riskLevels.value, value); }
function statusColor(status?: string) { return status === "HIT" ? "error" : status === "NOT_HIT" ? "success" : "warning"; }
function resetFilters() { filters.value = { taskId: undefined, agentId: undefined, ownerId: undefined, groupId: undefined, status: undefined, minScore: undefined, maxScore: undefined, speakerRole: undefined, riskLevel: undefined }; void refresh(); }
const conversationRows = computed(() => {
  if (conversationSummary.value.length) return conversationSummary.value;
  const grouped = new Map<string, InspectionResult[]>();
  results.value.forEach((item) => grouped.set(item.conversationId || item.id, [...(grouped.get(item.conversationId || item.id) || []), item]));
  return [...grouped.entries()].map(([conversationId, items]) => ({ conversationId, sourceFileName: undefined, messageCount: items.length, resultCount: items.length, averageScore: items.reduce((sum, item) => sum + (item.score || 0), 0) / Math.max(items.length, 1), hitCount: items.filter((item) => item.resultStatus === "HIT").length, highRiskCount: items.filter((item) => item.riskLevel === "HIGH").length, errorCount: items.filter((item) => item.resultStatus?.endsWith("ERROR")).length }));
});
async function refresh() { loading.value = true; try { if (filters.value.taskId) { const summary = await getBatchResultSummary(filters.value.taskId); conversationSummary.value = summary.conversations; results.value = []; total.value = summary.conversationCount; } else { const result = await listResults(filters.value, { current: page.value, size: pageSize.value }); results.value = result.records; conversationSummary.value = []; total.value = result.total; } } catch { message.error("结果加载失败"); } finally { loading.value = false; } }
async function changePage(current: number, size: number) { page.value = current; pageSize.value = size; await refresh(); }
async function showDetail(id: string) { conversationMessages.value = []; conversationResults.value = []; detailLoading.value = true; detailOpen.value = true; try { detail.value = await getResultDetail(id); } catch { message.error("结果详情加载失败"); detailOpen.value = false; } finally { detailLoading.value = false; } }
async function showConversation(row: ConversationResultSummary) { if (!filters.value.taskId) { const first = results.value.find((item) => item.conversationId === row.conversationId); if (first) return showDetail(first.id); return; } detailLoading.value = true; detailOpen.value = true; try { const data = await getConversationResultDetail(filters.value.taskId, row.conversationId); conversationMessages.value = data.messages || []; conversationResults.value = data.results || []; const first = conversationResults.value[0]; detail.value = first ? { result: first, task: { id: filters.value.taskId, name: `会话 ${row.conversationId}` }, message: conversationMessages.value.find((item: any) => item.id === first.messageId) || conversationMessages.value[0], conversation: data.conversation, summary: data.summary } : { task: { id: filters.value.taskId, name: `会话 ${row.conversationId}` }, conversation: data.conversation, summary: data.summary }; } catch { message.error("会话质检明细加载失败"); detailOpen.value = false; } finally { detailLoading.value = false; } }
async function exportCsv() { try { const response = await exportResults(filters.value); const url = URL.createObjectURL(response.data); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "iqc-results.csv"; anchor.click(); URL.revokeObjectURL(url); } catch { message.error("结果导出失败"); } }
function markResult(id:string,type:"CORRECT"|"FALSE_POSITIVE"|"FALSE_NEGATIVE"){Modal.confirm({title:type==="CORRECT"?"确认质检结论正确？":type==="FALSE_POSITIVE"?"标记为误判？":"标记为漏判？",content:"标注会追加保存，不会覆盖 AI 原始结果。",async onOk(){await createFeedback(id,{feedbackType:type});message.success("结果标注已保存");}});}
async function openReview(id:string){try{await requestReview(id,"从结果中心发起");message.success("已进入人工复核队列");}catch{message.error("发起复核失败");}}
async function saveAsSample(id:string,type:"POSITIVE"|"FALSE_POSITIVE"|"FALSE_NEGATIVE"){try{await createSample(id,{sampleType:type});message.success("已加入样本库");}catch{message.error("样本创建失败");}}
async function loadDictionaries() { try { const data = await getCachedDictionaries(["iqc_result_status", "iqc_risk_level"]); if (data.iqc_result_status?.length) resultStatuses.value = data.iqc_result_status; if (data.iqc_risk_level?.length) riskLevels.value = data.iqc_risk_level; } catch { /* 治理中心不可用时保留本地展示兜底。 */ } }
onMounted(() => { void refresh(); void loadDictionaries(); });
</script>

<template>
  <section class="page-intro"><div><span class="section-kicker">QUALITY RESULTS</span><h2>质检结果</h2><p>先看不满足项与扣分，再追溯判断理由、证据和改进建议。</p></div><a-button v-if="can('iqc:result:export')" @click="exportCsv">导出结果</a-button></section>
  <a-card :bordered="false" class="filter-card"><a-form layout="inline"><a-form-item label="任务"><a-input v-model:value="filters.taskId" allow-clear placeholder="任务 ID" style="width:140px"/></a-form-item><a-form-item label="Agent"><a-input v-model:value="filters.agentId" allow-clear placeholder="Agent ID" style="width:140px"/></a-form-item><a-form-item label="状态"><a-select v-model:value="filters.status" allow-clear style="width:120px"><a-select-option v-for="item in resultStatuses" :key="item.value" :value="item.value">{{item.label}}</a-select-option></a-select></a-form-item><a-form-item label="风险"><a-select v-model:value="filters.riskLevel" allow-clear style="width:110px"><a-select-option v-for="item in riskLevels" :key="item.value" :value="item.value">{{item.label}}</a-select-option></a-select></a-form-item><a-form-item label="分数"><a-input-number v-model:value="filters.minScore" :min="0" :max="100" placeholder="最低"/><span class="range-separator">-</span><a-input-number v-model:value="filters.maxScore" :min="0" :max="100" placeholder="最高"/></a-form-item><a-form-item><a-button type="primary" @click="refresh">筛选</a-button><a-button class="reset-button" @click="resetFilters">重置</a-button></a-form-item></a-form></a-card>

  <a-card :bordered="false"><div class="table-hint">结果按会话汇总展示；点击“会话明细”查看每句话的质检证据。</div><a-table :data-source="conversationRows" :loading="loading" :pagination="false" row-key="conversationId"><a-table-column title="会话" data-index="conversationId" :width="220"/><a-table-column title="消息数" data-index="messageCount" :width="90"/><a-table-column title="结果数" data-index="resultCount" :width="90"/><a-table-column title="平均得分" :width="110"><template #default="{record}"><strong>{{Number(record.averageScore || 0).toFixed(1)}}</strong></template></a-table-column><a-table-column title="命中" data-index="hitCount" :width="80"/><a-table-column title="高风险" :width="90"><template #default="{record}"><a-tag v-if="record.highRiskCount" color="error">{{record.highRiskCount}}</a-tag><span v-else>0</span></template></a-table-column><a-table-column title="异常" data-index="errorCount" :width="80"/><a-table-column title="操作" :width="150"><template #default="{record}"><a-button type="link" @click="showConversation(record)">会话明细</a-button></template></a-table-column></a-table><a-pagination v-if="total" v-model:current="page" v-model:page-size="pageSize" :total="total" show-size-changer class="pagination" @change="changePage"/></a-card>

  <a-drawer v-model:open="detailOpen" title="质检结果详情" width="min(860px, calc(100vw - 24px))"><a-spin :spinning="detailLoading"><template v-if="detail">
    <a-card :bordered="false" class="result-overview"><a-row :gutter="16"><a-col :span="6"><a-statistic title="得分" :value="detail.result?.score" suffix="分"/></a-col><a-col :span="6"><a-statistic title="总扣分" :value="detail.result?.deduction||0" prefix="-"/></a-col><a-col :span="6"><div class="overview-label">风险等级</div><a-tag :color="detail.result?.riskLevel==='HIGH'?'error':detail.result?.riskLevel==='MEDIUM'?'warning':'success'">{{riskLabel(detail.result?.riskLevel)}}</a-tag></a-col><a-col :span="6"><div class="overview-label">不满足项</div><strong class="violation-count">{{violations.length}} 项</strong></a-col></a-row></a-card>
    <a-alert v-if="!violations.length&&!diagnostics.length" type="success" show-icon message="本条消息未发现不满足项" description="所选规则均未命中。" class="section-block"/>
    <section v-if="violations.length" class="section-block"><div class="section-title"><div><h3>不满足项与扣分明细</h3><p>每一项均可追溯到规则、判断理由和证据。</p></div><a-tag color="error">共扣 {{detail.result?.deduction||0}} 分</a-tag></div>
      <a-card v-for="(item,index) in violations" :key="`${item.ruleId}-${index}`" size="small" class="violation-card"><template #title><span class="violation-index">{{index+1}}</span>{{ruleTitle(item,index)}}</template><template #extra><a-space><a-tag v-if="item.veto" color="error">一票否决</a-tag><a-tag :color="item.riskLevel==='HIGH'?'error':'warning'">{{riskLabel(item.riskLevel)}}</a-tag><strong class="deduction">-{{item.deduction||0}} 分</strong></a-space></template><a-descriptions :column="2" size="small"><a-descriptions-item label="规则编码">{{item.ruleCode||item.ruleId||'—'}}</a-descriptions-item><a-descriptions-item label="规则分类">{{item.category||'—'}}</a-descriptions-item><a-descriptions-item label="判断理由" :span="2">{{item.reason||'命中规则'}}</a-descriptions-item></a-descriptions><div v-if="ruleEvidence(item.ruleId).length" class="detail-group"><strong>命中证据</strong><a-alert v-for="(evidence,eIndex) in ruleEvidence(item.ruleId)" :key="eIndex" type="warning" show-icon :message="evidence.text||detail.result?.evidence||'命中当前消息'" :description="evidence.sequenceNo?`消息 #${evidence.sequenceNo}，位置 ${evidence.start??'-'}～${evidence.end??'-'}`:undefined"/></div><div v-if="ruleSuggestions(item.ruleId).length" class="detail-group"><strong>改进建议</strong><a-list size="small" :data-source="ruleSuggestions(item.ruleId)"><template #renderItem="{item:suggestion}"><a-list-item><a-list-item-meta :title="suggestion.title||'改进建议'" :description="suggestion.content"/></a-list-item></template></a-list></div></a-card>
    </section>
    <a-alert v-for="(item,index) in diagnostics" :key="`error-${index}`" type="error" show-icon :message="`${ruleTitle(item,index)}执行异常`" :description="item.reason" class="section-block"/>
    <section v-if="conversationMessages.length" class="section-block"><h3>会话消息明细（{{conversationMessages.length}} 条）</h3><a-list bordered size="small"><a-list-item v-for="item in conversationMessages" :key="item.id"><a-list-item-meta :title="`消息 #${item.sequenceNo} · ${item.speakerRole || '未知角色'}`" :description="item.content || '—'"/><a-tag v-if="conversationResults.some((result) => result.messageId === item.id)" color="error">有质检结果</a-tag></a-list-item></a-list></section>
    <section v-else class="section-block"><h3>原始消息</h3><a-card size="small"><p class="message-content">{{detail.message?.content||'—'}}</p></a-card></section>
    <a-collapse ghost class="trace-collapse"><a-collapse-panel key="trace" header="查看执行与版本追溯信息"><a-descriptions bordered :column="1" size="small"><a-descriptions-item label="执行实例">{{detail.result?.executionId||'—'}}</a-descriptions-item><a-descriptions-item label="任务">{{detail.task?.name||detail.result?.taskId}}</a-descriptions-item><a-descriptions-item label="消息 ID">{{detail.result?.messageId}}</a-descriptions-item><a-descriptions-item label="规则快照"><pre>{{detail.task?.ruleSnapshotJson||'—'}}</pre></a-descriptions-item><a-descriptions-item label="Agent 快照"><pre>{{detail.task?.agentSnapshotJson||'—'}}</pre></a-descriptions-item></a-descriptions></a-collapse-panel></a-collapse>
  </template></a-spin></a-drawer>
</template>

<style scoped>
.filter-card,.section-block{margin-bottom:16px}.range-separator{margin:0 6px}.reset-button{margin-left:8px}.pagination{margin-top:16px;text-align:right}.deduction{color:#cf1322;font-weight:600}.result-overview{margin-bottom:20px;background:var(--iqc-canvas)}.overview-label{margin-bottom:8px;color:var(--iqc-slate-600)}.violation-count{font-size:20px;color:#cf1322}.section-title{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:12px}.section-title h3,.section-block h3{margin:0 0 4px}.section-title p{margin:0;color:var(--iqc-slate-600)}.violation-card{margin-bottom:12px;border-left:3px solid #ff4d4f}.violation-index{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;margin-right:8px;border-radius:50%;color:#fff;background:#cf1322}.detail-group{display:grid;gap:8px;margin-top:14px}.message-content{margin:0;white-space:pre-wrap;line-height:1.8}.trace-collapse pre{max-height:220px;margin:0;overflow:auto;white-space:pre-wrap;word-break:break-all}
</style>
